import 'dart:convert';
import 'dart:math';
import 'dart:typed_data';

import 'package:dio/dio.dart';

import '../api/dio_interceptor.dart';
import '../api/end_points.dart';
import 'device_security_logger.dart';
import 'device_signature_interceptor.dart';
import 'request_canonicalizer.dart';

class DeviceChallenge {
  final String challengeId;

  /// 32 random bytes generated by the backend, base64.
  final String nonce;
  final int serverTime;

  const DeviceChallenge({required this.challengeId, required this.nonce, required this.serverTime});

  Uint8List get nonceBytes => base64Decode(nonce);

  factory DeviceChallenge.fromJson(Map<String, dynamic> json) => DeviceChallenge(
        challengeId: json['challengeId'] as String,
        nonce: json['nonce'] as String,
        serverTime: (json['serverTime'] as num).toInt(),
      );
}

class DeviceRegistrationRequest {
  final String challengeId;
  final List<String> certChain;

  /// Informational only: the backend must rely on the attestation, not on these.
  final bool attested;
  final String model;
  final String androidVersion;
  final String appVersion;

  const DeviceRegistrationRequest({
    required this.challengeId,
    required this.certChain,
    required this.attested,
    required this.model,
    required this.androidVersion,
    required this.appVersion,
  });

  Map<String, dynamic> toJson() => {
        'challengeId': challengeId,
        'certChain': certChain,
        'attested': attested,
        'model': model,
        'androidVersion': androidVersion,
        'appVersion': appVersion,
      };
}

class DeviceRegistration {
  final String deviceId;

  /// PENDING, ACTIVE or REVOKED.
  final String status;

  const DeviceRegistration({required this.deviceId, required this.status});

  factory DeviceRegistration.fromJson(Map<String, dynamic> json) => DeviceRegistration(
        deviceId: json['deviceId'] as String,
        status: json['status'] as String? ?? 'ACTIVE',
      );
}

/// The backend refused the attestation (403). Retrying on this run cannot help.
class DeviceEnrollmentRefused implements Exception {
  /// ATTESTATION_INVALID (app or phone not genuine) or DEVICE_NOT_SUPPORTED.
  final String code;

  /// Precise failed check, e.g. BAD_SIGNING_CERT, BOOT_NOT_VERIFIED, UNTRUSTED_ROOT.
  final String? reason;

  const DeviceEnrollmentRefused(this.code, this.reason);

  @override
  String toString() => 'DeviceEnrollmentRefused($code, $reason)';
}

/// Contract of GET /device/challenge and POST /device/register.
abstract class DeviceEnrollmentApi {
  /// Identifies where the deviceId comes from, so a mock deviceId is never
  /// reused once the real backend is plugged in.
  String get backendId;
  Future<DeviceChallenge> getChallenge();
  Future<DeviceRegistration> register(DeviceRegistrationRequest request);
}

/// Local stand-in until the backend endpoints exist.
class MockDeviceEnrollmentApi implements DeviceEnrollmentApi {
  final Random _random = Random.secure();

  @override
  String get backendId => 'mock';

  @override
  Future<DeviceChallenge> getChallenge() async {
    securityLog('[MOCK] GET /device/challenge (backend simulé, aucune requête réseau)');
    return DeviceChallenge(
      challengeId: RequestCanonicalizer.generateNonce(_random),
      nonce: base64Encode(List<int>.generate(32, (_) => _random.nextInt(256))),
      serverTime: DateTime.now().millisecondsSinceEpoch,
    );
  }

  @override
  Future<DeviceRegistration> register(DeviceRegistrationRequest request) async {
    securityLog('[MOCK] POST /device/register : ${request.certChain.length} certificats, '
        'attestée=${request.attested}, modèle=${request.model} (chaîne non vérifiée en mode simulé)');
    return DeviceRegistration(
      deviceId: 'mock-${RequestCanonicalizer.generateNonce(_random)}',
      status: 'ACTIVE',
    );
  }
}

class RemoteDeviceEnrollmentApi implements DeviceEnrollmentApi {
  final Dio dio;

  RemoteDeviceEnrollmentApi({required this.dio});

  static String get challengePath => '${EndPoints.baseUrl}/device/challenge';
  static String get registerPath => '${EndPoints.baseUrl}/device/register';

  /// No JWT exists yet, and these calls cannot be signed (no key yet).
  static Options get _options => Options(headers: {
        DioInterceptor.skipAuthHeader: 'true',
        DeviceSignatureInterceptor.skipSignatureHeader: 'true',
      });

  @override
  String get backendId => EndPoints.baseUrl;

  @override
  Future<DeviceChallenge> getChallenge() async {
    securityLog('GET $challengePath');
    final response = await dio.get(challengePath, options: _options);
    return DeviceChallenge.fromJson(_decode(response.data));
  }

  @override
  Future<DeviceRegistration> register(DeviceRegistrationRequest request) async {
    securityLog('POST $registerPath : ${request.certChain.length} certificats, attestée=${request.attested}');
    try {
      final response = await dio.post(registerPath, data: jsonEncode(request.toJson()), options: _options);
      return DeviceRegistration.fromJson(_decode(response.data));
    } on DioException catch (e) {
      // 403 { code, reason }: the attestation was checked and refused
      if (e.response?.statusCode == 403) {
        final body = _tryDecode(e.response?.data);
        throw DeviceEnrollmentRefused(
          body?['code'] as String? ?? 'ATTESTATION_INVALID',
          body?['reason'] as String?,
        );
      }
      rethrow;
    }
  }

  /// The shared Dio may be configured with ResponseType.plain.
  static Map<String, dynamic> _decode(Object? data) =>
      (data is String ? jsonDecode(data) : data) as Map<String, dynamic>;

  static Map<String, dynamic>? _tryDecode(Object? data) {
    try {
      return _decode(data);
    } catch (_) {
      return null;
    }
  }
}
